[package]
name = "dcs-test"
version = "0.1.0"
edition = "2021"

[dependencies]
dcs-client = { path = "../dcs-client" }
wayland-protocols = { version = "0.31", features = ["client"] }
ash = "0.38"
clap = { version = "4", features = ["derive"] }
libc = "0.2"

[package]
name = "dcs-tool"
version = "0.1.0"
edition = "2021"

[dependencies]
dcs-client = { path = "../dcs-client" }
clap = { version = "4", features = ["derive"] }
serde = { version = "1", features = ["derive"] }
serde_yaml = "0.9"
anyhow = "1"

